function at(id,time,where,effect="none",target,offset=0){const b=forces.get(id);if(!b)throw new Error(`Unknown force ${id}`);const dateTime=date(time);if(dateTime<b.visibility.showAt)b.visibility.showAt=dateTime;b.route=b.route.filter(s=>s.dateTime!==dateTime);b.route.push({id:`regional-${id}-${++serial}`,dateTime,...point(where,offset),size:b.size,effect,...(target?{firingTargetId:target}:{})});b.route.sort((a,b)=>a.dateTime.localeCompare(b.dateTime));}
function hide(id,time){forces.get(id).visibility.hideAt=date(time);}
function stop(id,time,effect="none"){const b=forces.get(id),prev=b.route.filter(s=>s.dateTime<=date(time)).at(-1);at(id,time,[prev.lat,prev.lng],effect);}
